import{bV as i,aL as a,u as e,G as t}from"./chunks/framework.BfzMay2U.js";const h=JSON.parse('{"title":"技术栈","description":"","frontmatter":{"title":"技术栈","date":"2026-11-13T16:07:10.000Z"},"headers":[],"relativePath":"kratos/fullstack/architech.md","filePath":"kratos/fullstack/architech.md"}'),n={name:"kratos/fullstack/architech.md"};function s(o,l,r,u,c,p){return a(),e("div",null,[...l[0]||(l[0]=[t(`<h1 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h1><h2 id="使用技术栈" tabindex="-1">使用技术栈 <a class="header-anchor" href="#使用技术栈" aria-label="Permalink to &quot;使用技术栈&quot;">​</a></h2><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><ul><li>Typescript，原生 JS-ES6</li><li>CSS3</li><li>Vue3</li><li>Vite</li><li>Element Plus</li><li>Uni-App</li></ul><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><ul><li>Go</li><li>gin</li><li>gorm</li><li>MySQL</li><li>redis</li><li>docker</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>0 起点：全栈闭环开发一套通用的权限管理系统(<code>casbin</code>实现)，一个即时聊天模块，以及落地一个包含 PC 管理端和 uni-app 移动端的社交交友平台</p><h3 id="前端-1" tabindex="-1">前端 <a class="header-anchor" href="#前端-1" aria-label="Permalink to &quot;前端&quot;">​</a></h3><ul><li>通过原生 JS+H5 写一个仿微信聊天交互界面</li><li>搭建前端开发结构以及封装常用工具方法以及 UI 组件(Ajax 请求、国际化支持、一键换肤、通用表格、通用表单、echarts 图表组件、EL 二次封装弹窗、抽屉等)</li><li>基于 Vue3+Vite+ElementPlus 开发通用权限管理系统（用户、部门、角色、权限/权限分类、字典、日志等模块）</li><li>整合前面基于 JS 以及 H5 实现的聊天界面，开发聊天相关的功能</li><li>在基础结构的上面开发社交/交友平台 PC 管理端（会员、红娘、实名认证、内容审核、牵线、投诉、工单等管理控制的实现）</li><li>基于 uni-app 开发社交交友 平台移动端（首页、动态页、即时消息页、个人中心页面、完善个人信息、提交实名认证、发起牵线、上传个人照片、发表动态、查看会员/动态/牵线/相册详情等）</li></ul><h3 id="后端-1" tabindex="-1">后端 <a class="header-anchor" href="#后端-1" aria-label="Permalink to &quot;后端&quot;">​</a></h3><ul><li>后端基础结构以及工具方法构建</li><li>基础结构上开发通用模块 RestFul API 的视线</li><li>开发社交交友平台后端的 API 接口实现</li><li>基于 docker 部署前后端</li></ul><blockquote><p>项目架构</p></blockquote><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户通过【PC 浏览器、移动端浏览器、微信小程序】通过 Nginx 访问到前端应用【PC 端管理应用、uni-app 移动端 H5 应用】</span></span>
<span class="line"><span>通过后端路由然后到中间件 【跨域支持、Token 鉴权、权限控制、日志记录等】</span></span>
<span class="line"><span>分别与通用权限管理服务、即时聊天服务、社交交友服务进行数据交流；最后数据服务使用 go-redis-&gt;redis、gorm-&gt;mysql；</span></span>
<span class="line"><span>最后整体使用  docker 进行容器化处理。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>跨端应用协作方式</p></blockquote><ul><li>PC 管理端：Vue3+Vite+TS+ElementPlus，负责权限、后台管理业务</li><li>移动端：uni-app 负责移动端业务与交互，复用同一套后端 API 体系</li><li>共同点：统一登录态 Token、统一错误处理、统一接口约定</li><li>静态资源：前端 build 后交给 nginx 托管；运行时与后端 API 交互</li></ul><blockquote><p>后端服务分层与路由分组</p></blockquote><ul><li>分层：Controller API-&gt;service 业务-&gt;Dao 数据访问-&gt;Model/DTO/VO</li><li>路由分组：Public(/api/pub)、Auth(/api 仅登录)、Perm(/api 登录+权限)</li><li>Swagger：统一接口文档入口，便于前后端联调</li><li>优雅启停：信号监听+Shutdown，保证服务可控退出</li></ul><blockquote><p>中间件链路</p></blockquote><ul><li>CORS：允许前端跨域访问</li><li>Token 鉴权：解析 Token，校验有效性；可做续期、刷新（响应头下发新 token）</li><li>权限控制价（casbin-RBAC）：基于角色的访问控制，按“用户、角色、资源、方法”判断，失败返回 403</li><li>操作审计：记录关键操作（谁在何时对什么做了什么），便于追踪</li></ul><blockquote><p>即时消息</p></blockquote><ul><li>api：联系人列表、历史消息、未读数、设置已读等可追溯数据</li><li>websocket：实时推送消息与回执，提示聊天体验</li><li>典型链路：发送消息-&gt;落库-&gt;返回成功-&gt;WS推送给对方在线客户端</li></ul><blockquote><p>资源存储分工</p></blockquote><ul><li>MYSQL：持久化业务数据（用户、角色、权限、消息、业务模块数据等）</li><li>redis：token、会话与热点缓存；提升鉴权与列表接口的性能</li><li>资源存储：附件、头像、图片等。通过 <code>/res</code> 统一对外访问</li><li>关键点：数据一致性（未读数、消息状态）与安全（上传大小、路径、鉴权）</li></ul>`,24)])])}const b=i(n,[["render",s]]);export{h as __pageData,b as default};
